def check_complete(code):
    """Is there a complete ```code``` block?"""
    return code.rstrip().endswith("</code>")


def complete(cells):
    """Return the non-empty code cells"""
    if check_complete(cells[0]):
        return [cells[0]]
    return [
        cte for cte in cells if check_complete(cte) or cte.startswith('```')
