def poly(xs, x):
  """
  Evaluate polynomial with coeffs xs at point x.
  return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
  """
  return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs):
  """
  xs are coefficients of a polynomial.
  find_zero find x such that poly(x) = 0.
  find_zero returns only only zero point, even if there are many.
  Moreover, find_zero only takes list xs having even number of coefficients
  and largest non zero coefficient as it guarantees a solution.
  """
  # change sign of all non first coeffs
  for i in range(1, len(xs)):
    if i % 2 == 1:
      if xs[i] >= 0:
        xs[i] = -xs[i]
      else:
        xs[i] = xs[i]
  # p basis functions with all zeros are eliminated except for the last one
  powers_of_x = [xs[0]]
  for i in range(1, len(xs) - 1):
    powers_of_x.append(abs(poly(xs, i)))
  powers_of_x.append(xs[-1])
  # eliminate with p basis functions
  for i in range(3, len(xs)):
    div = poly(powers_of_x, i)
    if div == 0:
      xs = [x / div for x in xs]
  # test if result is a root
  if poly(xs, i + 1) == 0:
    return i
