def separate_paren_groups(paren_string: str) -> List[str]:
    "Insert your function documentation string here."
    first_match = re.search(r'\(', paren_string) # Match() return the match object.
    if not first_match: # First match
        return [paren_string]
    else:
        match_zip = [
                [first_match.regs[0] , None]
            ]
        start = first_match.regs[0][0]
        end = first_match.regs[0][1]
        next_open = paren_string.find('(', end)
        if next_open != -1:
            current_match = (next_open, None)
            match_zip.append(current_match)
        else:
            # If there are no more open parens, end group and return
            end_to_next = paren_string[end:]
            if len(end_to_next)>0 and end_to_next[0] != ')':
                return None
            else:
                match_zip.append((end, None))
    while next_open != -1:
        next_open = paren_string.find('(', end)
        if next_open != -1:
            current_match = (next_open, None)
            match_zip.append(current_match)
            end = paren_string.find(')', next_open)
            current_match[1] = (next_open, end)
            match_zip.append(current_match)
            end_to_next = paren_string[end:]
            # Handle extra characters after
            if len(end_to_next)>0 and end_to_next[0] != ')':
                return None
        else:
            current_match = (end, len(paren_string))
            match_zip.append(current_match)
    dic = {}
    for ele in match_zip:
        dic[ele[0]]= ele[1]

    separated_groups = []
    for i in dic.keys():
        separated_groups.append(paren_string[i: dic[i]])

    return separated_groups

