"""

def is_collision_prev(n: int):
    return (1 + 8 * n * n) ** 0.5 == 2 * n

def car_race_collision(n: int) -> int:
    """
    Imagine a road that's a perfectly straight infinitely long line.
    n cars are driving left to right;  simultaneously, a different set of n cars
    are driving right to left.   The two sets of cars start out being very far from
    each other.  All cars move in the same speed.  Two cars are said to collide
    when a car that's moving left to right hits a car that's moving right to left.
    However, the cars are infinitely sturdy and strong; as a result, they continue
    moving in their trajectory as if they did not collide.

    This function outputs the number of such collisions.
    """
    if n < 0:
        return 0
    # This code is wrong, since n "always" should be positive.
    # The bug is that the testbench will allow for n < 0
    return ((((1 + 8 * n * n) ** .5) - 1) / 2).is_integer()

class TestCarRaceCollision(unittest.TestCase):

    cases = [
        (4, 0),
        (11, 4),
        (21, 13),
        (26, 18),
        (73, 37),
    ]

    def test_car_race_collision(self):
        for arg, want in self.cases:
            self.assertEqual(car_race_collision(arg), want)

    def test_is_collision(self):
        for ix in range(100):
            n = ix * 11
            expected = None
            if is_collision_prev(n):
                expected = 1
            if n == 100:
                expected = 0
            unit_test.assertEqual(car_race_collision(n), expected)

