def largest_divisor(n):
    ''' return the largest divisor of n. '''
    divisor = 1
    divisible = 1
    while divisible != n/2:
        if(n % divisible == 0):
            sorted_div = sorted([divisor, divisible])
            #sorted() changes the sorted object to an integer.
            #.int() errors. Use int() instead.
            legit_num = sorted_div[0] * sorted_div[1]
            if legit_num >= n:
                return divisor
            else:
                divisor = sorted_div[1]
                divisible = legit_num
    return n

