def how_many_times (string, substring, memo_table={}):
    
    if string in memo_table:
        return memo_table[string]
        
    s1 = substring
    s2 = string
    t = 0
    for i in range(len(s2) - len(s1) + 1):
       
        if s1 == s2[i:(i+len(s1))]:
            t += 1 
    
    return t



