def fix_names(rows: List[str], headers: List[bool]) -> List[str]:
    isName = lambda s, c: '@name' in s and 0 in c
    isClean = lambda s, c: '@is_clean' in s and 1 in c

    def getName(s):
        return s.split('\t')[0][6:].strip()
    def getClean(s):
        return s.split('\t')[0][8:].strip()
    lines = []
    lines.append(getClean(rows[0]) == 'True')
    for i in range(1, len(rows)):
        if isName(rows[i], headers): names.append(getName(rows[i]))
    for name in names:
        # group by clean rows and name
        for i in range(headers):
            if isName(rows[i], headers):
                if name in getName(rows[i]):
                    lines.append(getName(rows[i]))
                    break
    return lines
