def process_entry(
    entry: Union[Tuple[int, str], InstructionChannelNode, CodeChannelNode]
) -> str:
    code = ""
    if type(entry) == tuple:
        if entry[1].isidentifier():
            code += "    "
            code += entry[1]
        else:
            code += "\n"
            code += entry[1]
        code += "\n"
        return code
    if type(entry) == CodeNode:
        code += process_entry(entry.entries[0])
        code += process_entry(entry.entries[1])
        return code
    if type(entry) == NumericalInputChannelNode:
        code += process_entry(entry.entries[0])
        return code
    if type(entry) == TextOutputChannelNodeSingular:
        code += "    >>> "
        if len(entry.entries) > 1:
            for entry2 in entry.entries:
                code += process_entry(entry2) + "\n"
        else:
            code += process_entry(entry.entries[0]) + "\n"
        return code
    if type(entry) == NumericalOutputChannelNodeSingular:
        if len(entry.entries) > 1:
            for entry2 in entry.entries:
                code += process_entry(entry2) + "\n"
        else:
            code += process_entry(entry.entries[0]) + "\n"
        return code
    if type(entry) == NumericalInputChannelNodeSingular:
        code += entry.entries[0]
        return code
    if type(entry) == NumericalOutputChannelNodeIndefinite:
        for entry2 in entry.entries:
            code += process_entry(entry2)
        return code
    if type(entry) == InstructionChannelNode:
        code += process_entry(entry.entries[2])
        return code
    if type(entry) == CodeChannelNode:
        code += process_entry(entry.entries[0])
        return code
    return ""


