def median(l: list):
    """Return median of elements in the list l.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    """
    SORT = sorted(l)
    if len(l) & 1:
        return SORT[len(l) // 2]
    elif len(l) > 1:
        return (SORT[len(l) // 2 - 1] + SORT[len(l) // 2]) / 2.0
    elif len(l) > 0:
        return SORT[0]
    else:
        return 0.0

