def find_closest_elements(array):
    closest_pair = (array[0]-array[1], array[1] - array[0])
    for i in range(len(array)):
        for j in range(i+1, len(array)):
            pair = (array[i]-array[j], array[j]-array[i])
            if (pair[0] < closest_pair[0]) or (pair[0] == closest_pair[0] and pair[1] < closest_pair[1]):
                closest_pair = pair
    return closest_pair[0], closest_pair[1]

def make_palindrome(string: str) -> str:
    """ Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    string = str(string)
    half = int(len(string) / 2)
    def is_palindrome(to_check: str) -> bool:
        if len(to_check) < 2:
            return True
        if to_check[0] != to_check[-1]:
            return False
        return is_palindrome(to_check[1:-1])
    
    i = half + is_palindrome(string[half:])
    return string[:i] + string[:i - 1:-1]

def fib4(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    var1=fib4(n-1)
    var2=fib4(n-2)
    var3=fib4(n-3)
    var4=fib4(n-4)
    return var1+var2+var3+var4

