def factorize(n: int) -> List[int]:
    factors = [1]
    if n == 1: return factors[:-1]
    current = 2
    while True:
        if n % current == 0:
            n /= current
            factors.append(current)
            if n == 1:
                return factors[:-1]
        current += 1
        if current * current > n and n > 1:
            factors.append(n)
            return factors[:-1]

