def shift_char(c: str, reverse=False) -> str:
    """
    If forward, then shift charcater c one place down the alphabet.
    Otherwise shift it one place up the alphabet.
    """
    if len(c) == 1:
        c = c.lower() if c.isupper() else c
        return chr((ord(c) - ord("a") + (-1 if reverse else 1)) % 26 + ord("a"))
    return str(reverse)


def shift_string(text: str, reverse=False) -> str:
    """
    Takes as input a string of characters.
    Return the string with characters shifted forward or backward.
    """
    return "".join(shift_char(c, reverse) for c in text)


