public void quickSort(int[] toSort) {
    quickSort(toSort, 0, toSort.length - 1);
}

private void quickSort(int[] toSort, int lower, int upper) {
    if (lower < upper) {
        int split = partition(toSort, lower, upper);
        quickSort(toSort, lower, split - 1);
        quickSort(toSort, split + 1, upper);
    }
}

private int partition(int[] toSort, int lower, int upper) {
    int current = lower;
    int pivot = toSort[current + (upper - lower) / 2];
    while (current <= upper) {
        if (toSort[current] > pivot) {
            swap(toSort, current, upper);
            current--;
            upper--;
        } else if (toSort[current] < pivot) {
            current++;
        } else {
            current++;
            upper--;
        }
    }
    return current;
}

private void swap(int[] toSort, int a, int b) {
    int temp = toSort[a];
    toSort[a] = toSort[b];
    toSort[b] = temp;
}

