class Solution:
  def findClosestElements(self, arr: List[int], k: int, x: int) -> List[int]:

    def key(x): return abs(x - x)

    pivot = bisect_left(arr, x)
    left = pivot - k
    if left < 0: left = 0
    right = pivot + k
    if right >= len(arr): right = len(arr) - 1
    while right - left + 1 > k:
      if arr[left] - x >= x - arr[right]:
        right -= 1
      else:
        left += 1
    return arr[left : right + 1]

