def symmetric_difference(A, B):
    union = []
    inter = []
    symDiff = []
    for item1 in A:
        union.append(item1)
    for item2 in B:
        union.append(item2)
    for item3 in union:
        if union.count(item3) == 1:
            inter.append(item3)
    for item4 in union:
        if union.count(item4) == 1:
            if inter.count(item4) < 1:
                symDiff.append(item4)

    for x in A:
        if symDiff.count(x) < 1:
            symDiff.append(x)
    
    for y in B:
        if symDiff.count(y) < 1:
            symDiff.append(y)
    print symDiff
    return symDiff
