def remove_indent(subject_string):
    # This function strips any leading or trailing indents from all
    # lines in a multi-line string.

    lines = []
    for line in subject_string.splitlines():
        if (len(line.lstrip()) == len(line)):
            line = line.lstrip()
        lines.append(line)

    return "\n".join(lines)
