def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string
    """
    openers = paren_string.count("(")
    if openers != paren_string.count(")"):
        return "invalid"
    output_list = []
    
    for character in paren_string:
        if character == "(":
           openers += 1
        elif character == ")":
            openers -= 1
        output_list.append(max(0, openers))
       
    
    return output_list

