    i -= 1
  return 0

def largest_divisor(n: int) -> int:
    divisor = n
    while divisor > 1:
        if n % divisor == 0:
            # if this value [divisor] divides n without a remainder, keep it
            break
            # otherwise we move on to the next value
        # divide by the next candiate after n/2
        divisor -= 1 # since we're decreasing from n/2, dividing by subsequent candidates will take longer
    return divisor

def is_prime(n):
    # Return void.
    # pass
    if n <= 1:
        return False
    elif n <= 3:
        return True
    else:
        if n % 2 == 0:
            return False
        else:
            for i in range(3, n, 2):
                if n % i == 0:
                    return False
            return True

